/**
 * RLHF Feedback Log — tool-local actions.
 *
 * Category: AI / LLM Product Management (squad S12b)
 * Tool:     Pairwise-comparison dataset — prompt, response A, response B,
 *           winner, reviewer, reason.
 *
 * Agent surface: tool.rlhf_log.*
 * Backing CRUD : workspace.rlhf_pair.* (auto-generated by defineCrudActions
 *                in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (see mood-tracker.ts for the analog) ──────
 * Pairs are a record-keeping entity — generic create / list / update /
 * delete already exist via workspace.rlhf_pair.*. This file adds:
 *
 *   1. list_state         — total, byWinner {A,B,tie}, winRateA (A over
 *                           decisive comparisons, ties excluded), tieRate.
 *   2. record_comparison  — log one pairwise judgement (loggedAt → now).
 *
 * Entity kind "workspace:rlhfPair" (kindFromToolId of "workspace.rlhf_pair")
 * matches the browser sync engine, so MCP writes round-trip into the UI.
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverUpsertEntity } from "../server-store";
import type { RlhfPair } from "@/lib/stores/workspace-types";

const KIND_RLHF = "workspace:rlhfPair";

const WINNERS = ["A", "B", "tie"] as const;
const WinnerSchema = z.enum(WINNERS);

const ws = () => useWorkspaceStore.getState();

const round2 = (n: number) => Math.round(n * 100) / 100;

function summarize(items: RlhfPair[]) {
  const byWinner: Record<RlhfPair["winner"], number> = { A: 0, B: 0, tie: 0 };
  for (const p of items) {
    if (p.winner in byWinner) byWinner[p.winner] += 1;
  }
  // Decisive = comparisons with a clear winner (ties excluded). winRateA is
  // A's share of those — the headline preference signal. 0 when no decisive
  // comparisons exist (avoids NaN).
  const decisive = byWinner.A + byWinner.B;
  return {
    total: items.length,
    byWinner,
    winRateA: decisive ? round2(byWinner.A / decisive) : 0,
    tieRate: items.length ? round2(byWinner.tie / items.length) : 0,
  };
}

// ──────── tool.rlhf_log.list_state ────────
registry.register({
  id: "tool.rlhf_log.list_state",
  toolId: "tool.rlhf_log",
  name: "list_state",
  category: "read",
  description:
    "Summarise the RLHF pairwise dataset. Returns {total, byWinner: {A, B, tie}, winRateA (0..1, A's share of decisive comparisons — ties excluded), tieRate (0..1, ties over all comparisons)}.",
  paramsSchema: z.object({}),
  handler: async () => summarize(ws().rlhfPairs ?? []),
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<RlhfPair>(ctx.userId, KIND_RLHF);
    return summarize(items);
  },
});

// ──────── tool.rlhf_log.record_comparison ────────
registry.register({
  id: "tool.rlhf_log.record_comparison",
  toolId: "tool.rlhf_log",
  name: "record_comparison",
  category: "write",
  requiresConfirmation: false,
  description:
    "Record one pairwise comparison. winner is 'A' | 'B' | 'tie'. loggedAt defaults to now. Returns {added: true, id}.",
  paramsSchema: z.object({
    prompt: z.string().min(1).max(8000),
    responseA: z.string().max(8000),
    responseB: z.string().max(8000),
    winner: WinnerSchema,
    reviewer: z.string().max(200).optional(),
    reason: z.string().max(2000).optional(),
    loggedAt: z.string().optional().describe("ISO timestamp; defaults to now when omitted."),
  }),
  handler: async (params) => {
    const pair: RlhfPair = {
      id: crypto.randomUUID(),
      prompt: params.prompt,
      responseA: params.responseA,
      responseB: params.responseB,
      winner: params.winner,
      reviewer: params.reviewer,
      reason: params.reason,
      loggedAt: params.loggedAt ?? new Date().toISOString(),
    };
    ws().upsertRlhfPair(pair);
    return { added: true, id: pair.id };
  },
  mcpHandler: async (params, ctx) => {
    const pair: RlhfPair = {
      id: crypto.randomUUID(),
      prompt: params.prompt,
      responseA: params.responseA,
      responseB: params.responseB,
      winner: params.winner,
      reviewer: params.reviewer,
      reason: params.reason,
      loggedAt: params.loggedAt ?? new Date().toISOString(),
    };
    await serverUpsertEntity<RlhfPair>(ctx.userId, KIND_RLHF, pair);
    return { added: true, id: pair.id };
  },
});
